import React, { useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { useAuth } from '../auth/AuthContext';
import { mockEquipments } from '../data/mockEquipments';
import BorrowModal from '../components/BorrowModal';
import AuthModal from '../components/AuthModal';

export default function EquipmentDetail() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { user } = useAuth();

  // ดึงข้อมูลอุปกรณ์ตาม ID
  const equipment = mockEquipments.find(item => item.id === parseInt(id)) || mockEquipments[0];

  const [borrowModalOpen, setBorrowModalOpen] = useState(false);
  const [authModalOpen, setAuthModalOpen] = useState(false);

  // ข้อมูลจำลองรีวิว
  const [reviews, setReviews] = useState([
    { id: 1, userName: "สมชาย สายลุย", rating: 5, comment: "อุปกรณ์สภาพใหม่มาก ใช้งานได้ดีเยี่ยมครับ!", date: "2026-11-01" },
    { id: 2, userName: "กฤษฎา คงแก้ว", rating: 4, comment: "แบตเตอรี่อึดตามสเปก แต่กระเป๋าหนักไปนิดนึง", date: "2026-11-05" }
  ]);

  // ฟอร์มเขียนรีวิว (สำหรับคนที่คืนแล้ว)
  const [newRating, setNewRating] = useState(5);
  const [newComment, setNewComment] = useState('');
  const [hasReturned] = useState(true); // สมมติสถานะว่ายืมและคืนแล้ว

  const handleAddReview = (e) => {
    e.preventDefault();
    if (!newComment.trim()) return;

    const newEntry = {
      id: Date.now(),
      userName: user?.name || user?.username || 'นักศึกษา',
      rating: newRating,
      comment: newComment,
      date: new Date().toISOString().split('T')[0]
    };

    setReviews([newEntry, ...reviews]);
    setNewComment('');
    alert('บันทึกรีวิวเรียบร้อยแล้ว ขอบคุณครับ!');
  };

  const handleBorrowClick = () => {
    if (!user || user.role === 'guest') {
      setAuthModalOpen(true);
    } else {
      setBorrowModalOpen(true);
    }
  };

  return (
    <div style={{ maxWidth: '1000px', margin: '30px auto', padding: '0 20px' }}>
      {/* ปุ่มย้อนกลับไปหน้า Home */}
      <button 
        onClick={() => navigate('/')}
        style={{
          background: '#FFFFFF',
          border: '1px solid #CBD5E1',
          padding: '8px 16px',
          borderRadius: '8px',
          cursor: 'pointer',
          marginBottom: '20px',
          fontWeight: '600',
          color: '#475569',
          display: 'flex',
          alignItems: 'center',
          gap: '6px'
        }}
      >
        ⬅️ กลับหน้าหลัก (Home)
      </button>

      {/* รายละเอียดอุปกรณ์ */}
      <div style={{
        background: '#FFFFFF',
        borderRadius: '16px',
        overflow: 'hidden',
        boxShadow: '0 4px 15px rgba(0,0,0,0.05)',
        border: '1px solid #E2E8F0',
        marginBottom: '30px'
      }}>
        <div style={{ display: 'flex', flexWrap: 'wrap' }}>
          <div style={{ flex: '1 1 400px', height: '350px', background: '#F8FAFC' }}>
            <img src={equipment.image} alt={equipment.name} style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
          </div>

          <div style={{ flex: '1 1 400px', padding: '30px', display: 'flex', flexDirection: 'column', justifyContent: 'space-between' }}>
            <div>
              <span style={{ background: '#DBEAFE', color: '#1E3A8A', padding: '4px 12px', borderRadius: '20px', fontSize: '13px', fontWeight: '600' }}>
                {equipment.category}
              </span>
              <h2 style={{ fontSize: '26px', color: '#1E293B', margin: '12px 0' }}>{equipment.name}</h2>
              <p style={{ color: '#475569', fontSize: '15px', lineHeight: '1.6' }}>
                {equipment.description || 'ไม่มีคำอธิบายเพิ่มเติมสำหรับอุปกรณ์ชิ้นนี้'}
              </p>

              <div style={{ marginTop: '20px', display: 'flex', gap: '20px', fontSize: '14px', color: '#64748B' }}>
                <div>📦 สต็อกทั้งหมด: <strong>{equipment.totalStock} ชิ้น</strong></div>
                <div>✨ คงเหลือ: <strong style={{ color: equipment.availableStock > 0 ? '#16A34A' : '#DC2626' }}>{equipment.availableStock} ชิ้น</strong></div>
              </div>
            </div>

            <div style={{ marginTop: '30px' }}>
              {equipment.availableStock > 0 ? (
                <button 
                  onClick={handleBorrowClick}
                  style={{
                    width: '100%',
                    padding: '14px',
                    background: '#2563EB',
                    color: '#FFFFFF',
                    border: 'none',
                    borderRadius: '10px',
                    fontWeight: '700',
                    fontSize: '16px',
                    cursor: 'pointer'
                  }}
                >
                  ยืมอุปกรณ์นี้
                </button>
              ) : (
                <button disabled style={{ width: '100%', padding: '14px', background: '#94A3B8', color: '#FFF', border: 'none', borderRadius: '10px', fontWeight: '700' }}>
                  ของหมดชั่วคราว
                </button>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* ส่วนรีวิวอุปกรณ์ (Review Section) */}
      <div style={{ background: '#FFFFFF', padding: '30px', borderRadius: '16px', border: '1px solid #E2E8F0', boxShadow: '0 4px 15px rgba(0,0,0,0.05)' }}>
        <h3 style={{ fontSize: '20px', color: '#1E293B', marginBottom: '20px' }}>⭐ รีวิวจากผู้เคยยืมใช้งาน</h3>

        {/* ฟอร์มเขียนรีวิว เฉพาะ Member ที่คืนแล้ว */}
        {user && user.role === 'member' && hasReturned && (
          <form onSubmit={handleAddReview} style={{ background: '#F8FAFC', padding: '20px', borderRadius: '12px', marginBottom: '24px', border: '1px solid #E2E8F0' }}>
            <h4 style={{ margin: '0 0 10px 0', fontSize: '15px', color: '#334155' }}>✍️ เขียนรีวิวหลังคืนอุปกรณ์</h4>
            <div style={{ marginBottom: '12px', display: 'flex', alignItems: 'center', gap: '10px' }}>
              <span style={{ fontSize: '14px', color: '#475569' }}> ให้คะแนน:</span>
              <select value={newRating} onChange={(e) => setNewRating(Number(e.target.value))} style={{ padding: '6px 10px', borderRadius: '6px', border: '1px solid #CBD5E1' }}>
                <option value={5}>⭐⭐⭐⭐⭐ (5 ดาว - ดีมาก)</option>
                <option value={4}>⭐⭐⭐⭐ (4 ดาว - ดี)</option>
                <option value={3}>⭐⭐⭐ (3 ดาว - ปานกลาง)</option>
                <option value={2}>⭐⭐ (2 ดาว - พอใช้)</option>
                <option value={1}>⭐ (1 ดาว - ควรปรับปรุง)</option>
              </select>
            </div>
            <textarea 
              rows="3" 
              placeholder="แชร์ความเห็นเกี่ยวกับสภาพอุปกรณ์หรือการใช้งาน..."
              value={newComment}
              onChange={(e) => setNewComment(e.target.value)}
              style={{ width: '100%', padding: '10px', borderRadius: '8px', border: '1px solid #CBD5E1', marginBottom: '10px', outline: 'none', fontSize: '14px' }}
            />
            <button type="submit" style={{ background: '#16A34A', color: '#FFF', border: 'none', padding: '8px 18px', borderRadius: '6px', fontWeight: '600', cursor: 'pointer' }}>
              ส่งรีวิว
            </button>
          </form>
        )}

        {/* รายการรีวิว */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
          {reviews.map((rev) => (
            <div key={rev.id} style={{ padding: '16px', borderRadius: '10px', border: '1px solid #F1F5F9', background: '#FAFAFA' }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '6px' }}>
                <strong>👤 {rev.userName}</strong>
                <span style={{ color: '#F59E0B' }}>{'⭐'.repeat(rev.rating)}</span>
              </div>
              <p style={{ margin: '0 0 6px 0', fontSize: '14px', color: '#475569' }}>{rev.comment}</p>
              <span style={{ fontSize: '12px', color: '#94A3B8' }}>📅 วันที่: {rev.date}</span>
            </div>
          ))}
        </div>
      </div>

      {/* Modals */}
      <AuthModal isOpen={authModalOpen} onClose={() => setAuthModalOpen(false)} />
      <BorrowModal isOpen={borrowModalOpen} onClose={() => setBorrowModalOpen(false)} equipment={equipment} />
    </div>
  );
}
